const msg = $input.first().json.choices?.[0]?.message;
const call = msg?.tool_calls?.[0];
let result;
try {
  result = call ? JSON.parse(call.function.arguments) : { error: 'no_tool_call', raw: msg };
} catch (e) {
  result = { error: 'parse_error', raw: call?.function?.arguments };
}
return [{ json: result }];
